def generate_sft_dataset(output_path: Path):
    output_path.parent.mkdir(parents=True, exist_ok=True)
    
    categories = [
        ("Greetings", GREETINGS_RAW),
        ("CS Core", CS_CORE_RAW),
        ("Non-CS Polite Refusal", NON_CS_RAW),
        ("CS Code", CS_CODE_RAW),
        ("CS Fallback", FALLBACK_RAW),
    ]
    
    total_written = 0
    with open(output_path, "w", encoding="utf-8") as f:
        for cat_name, raw_list in categories:
            # Her kategoriden tam 100 örnek al
            selected = raw_list[:100]
            if len(selected) < 100:
                raise ValueError(f"Kategori '{cat_name}' 100'den az örnek içeriyor: {len(selected)}")
            for user, assistant in selected:
                item = {
                    "system": SYSTEM_PROMPT,
                    "user": user.strip(),
                    "assistant": assistant.strip(),
                }
                f.write(json.dumps(item, ensure_ascii=False) + "\n")
                total_written += 1
                
    print(f"Başarıyla {total_written} örnek kaydedildi: {output_path}")

if __name__ == "__main__":
    out_file = Path("data/sft/train.jsonl")
    generate_sft_dataset(out_file)
